do $$ begin if current_database() !~ '^dorm_repair_v2_(dev|test(_[a-z0-9]+)?)$' then raise exception 'Unsafe D target'; end if; end $$;
select guard_key from public.system_guard where guard_key='rbac-admin' for update;
do $$ begin
 if exists(select 1 from public.sys_user) then
  if to_regclass('pg_temp.c7_confirmed_user_grants') is null then raise exception 'D migration requires confirmed per-user new permission mapping'; end if;
 elsif exists(select 1 from public.sys_role where code not in ('ADMIN','STUDENT','REPAIRER')) or exists(select 1 from public.system_guard where initialized_user_id is not null) then raise exception 'Unknown empty-user role templates'; end if;
end $$;
create temporary table if not exists c7_confirmed_user_grants(user_id bigint,permission_code varchar(80),primary key(user_id,permission_code)) on commit drop;
insert into public.sys_permission(code,description,module) values ('address:own','本人地址簿','V2_FOUNDATION'),('residency:own','本人经确认入住关系','V2_FOUNDATION'),('residency:manage','确认与撤销入住关系','V2_FOUNDATION'),('draft:own','本人报修资料准备','V2_FOUNDATION');
do $$ begin if exists(select 1 from c7_confirmed_user_grants g left join public.sys_user u on u.id=g.user_id where u.id is null or g.permission_code not in ('address:own','residency:own','residency:manage','draft:own')) then raise exception 'Invalid D authorization mapping'; end if; end $$;
insert into public.sys_role(code,name) select distinct 'D7_U_'||user_id,'D阶段独立补充授权' from c7_confirmed_user_grants;
insert into public.sys_role_permission select r.id,p.id from c7_confirmed_user_grants g join public.sys_role r on r.code='D7_U_'||g.user_id join public.sys_permission p on p.code=g.permission_code;
insert into public.sys_user_role select distinct g.user_id,r.id from c7_confirmed_user_grants g join public.sys_role r on r.code='D7_U_'||g.user_id;
insert into public.sys_role_permission select r.id,p.id from public.sys_role r cross join public.sys_permission p where not exists(select 1 from public.sys_user) and p.code in ('address:own','residency:own','residency:manage','draft:own') and (r.code='ADMIN' or (r.code='STUDENT' and p.code<>'residency:manage'));
update public.sys_user set auth_version=auth_version+1,version=version+1 where id in(select user_id from c7_confirmed_user_grants);
do $$ begin if exists(select 1 from public.sys_user) and not exists(select 1 from public.sys_user u where u.enabled and not exists(select 1 from public.sys_permission p where p.available and not exists(select 1 from public.sys_user_role ur join public.sys_role r on r.id=ur.role_id and r.enabled join public.sys_role_permission rp on rp.role_id=r.id where ur.user_id=u.id and rp.permission_id=p.id))) then raise exception 'D mapping loses full custodian'; end if; end $$;
create table public.user_address(id bigint generated by default as identity primary key,user_id bigint not null references public.sys_user(id) on delete restrict,room_id bigint not null references public.room(id) on delete restrict,contact_name varchar(80) not null,phone varchar(30) not null,location_text varchar(200) not null default '',is_default boolean not null default false,enabled boolean not null default true,version integer not null default 0 check(version>=0),created_at timestamptz not null default current_timestamp);
create unique index uq_address_default on public.user_address(user_id) where enabled and is_default;
create index ix_address_owner on public.user_address(user_id,id);
create table public.room_resident(id bigint generated by default as identity primary key,user_id bigint not null references public.sys_user(id) on delete restrict,room_id bigint not null references public.room(id) on delete restrict,valid_from timestamptz not null,valid_to timestamptz not null,enabled boolean not null default true,verified_by bigint not null references public.sys_user(id) on delete restrict,version integer not null default 0 check(version>=0),created_at timestamptz not null default current_timestamp,check(valid_from<valid_to));
create index ix_resident_access on public.room_resident(user_id,room_id,enabled,valid_from,valid_to);
create table public.repair_draft(id bigint generated by default as identity primary key,owner_id bigint not null references public.sys_user(id) on delete restrict,current_revision integer not null default 0 check(current_revision>=0),version integer not null default 0 check(version>=0),state varchar(20) not null default 'EDITABLE' check(state in ('EDITABLE','ABANDONED')),created_at timestamptz not null default current_timestamp);
create index ix_draft_owner on public.repair_draft(owner_id,id);
create table public.repair_draft_revision(id bigint generated by default as identity primary key,draft_id bigint not null references public.repair_draft(id) on delete restrict,revision_no integer not null check(revision_no>0),previous_revision_id bigint references public.repair_draft_revision(id) on delete restrict,description varchar(2000),category_id bigint references public.repair_category(id) on delete restrict,item_id bigint references public.repair_item(id) on delete restrict,facility_id bigint references public.facility(id) on delete restrict,source_address_id bigint references public.user_address(id) on delete restrict,address_snapshot jsonb,category_snapshot jsonb,item_snapshot jsonb,facility_snapshot jsonb,time_mode varchar(10) not null default 'ANY' check(time_mode in ('ANY','WINDOW')),window_start timestamptz,window_end timestamptz,unattended_willing boolean not null default false,estimated_minutes integer check(estimated_minutes between 1 and 1440),estimate_source varchar(30) check(estimate_source in ('ITEM_DEFAULT','MANUAL')),estimate_reason varchar(300),complete boolean not null default false,created_at timestamptz not null default current_timestamp,unique(draft_id,revision_no),check((time_mode='ANY' and window_start is null and window_end is null) or(time_mode='WINDOW' and window_start is not null and window_end is not null and window_start<window_end)));
create function public.immutable_draft_revision() returns trigger language plpgsql as $$ begin raise exception 'Draft revisions are immutable' using errcode='42501'; end $$;
create trigger draft_revision_immutable before update or delete on public.repair_draft_revision for each row execute function public.immutable_draft_revision();
insert into public.audit_event(action,target_type,request_id,details) values ('D7_MIGRATED','SCHEMA','migration_d7','{}');
